defined('_JEXEC') or die;
use Nicode\Component\NicodeWebMonitor\Administrator\Service\SiteHealth;
$counts=['recent'=>0,'review'=>0,'never'=>0];$priorities=['critical'=>0,'review'=>0,'updates'=>0,'unknown'=>0];
foreach($sites as $row){
    $counts[($states[$row['check_state']??'never_checked']??['Estado desconocido','warning','review'])[2]]++;
    foreach($priorities as $filter=>$count)if(SiteHealth::matches($row['health'],$filter))$priorities[$filter]++;
}
$visible=count(array_filter($sites,static fn($s)=>SiteHealth::matches($s['health'],$priorityFilter)));
$healthBadge=static function(array $indicator)use($escape){return '<span class="nwm-health-pill nwm-health-pill--'.$indicator['tone'].'" title="'.$escape($indicator['detail']).'">'.$escape($indicator['label']).'</span>';};
?>
<section class="nwm-metrics" aria-label="Resumen de inventario"><?php foreach([['all','Sitios registrados',count($sites),'server'],['recent','Inventario reciente',$counts['recent'],'check'],['review','Requieren revisión',$counts['review'],'alert'],['never','Sin comprobar',$counts['never'],'clock']] as [$group,$label,$count,$symbol]): ?><a class="nwm-metric nwm-metric--<?= $group ?>" href="#nwm-sites" data-nwm-filter="<?= $group ?>"><span class="nwm-metric-icon"><?= $icon($symbol) ?></span><span><strong><?= (int)$count ?></strong><span><?= $label ?></span></span></a><?php endforeach; ?></section>
<section id="nwm-sites" class="nwm-sites-section" aria-label="Sitios registrados">
<div class="nwm-section-heading"><div><p class="nwm-section-label">Directorio de sitios</p><h2>Sitios registrados <span class="nwm-count"><?= count($sites) ?></span></h2></div><span class="nwm-utc-note">Fechas en UTC</span></div>
<p class="nwm-section-intro">La prioridad reúne versiones, actualizaciones y señales compartidas. Inventario reciente indica cuándo se consultó; no significa que todo esté al día.</p>
<?php if($sites): ?>
<nav class="nwm-priority-filters" aria-label="Prioridades"><?php foreach(['all'=>'Todos','critical'=>'Prioritarias','review'=>'Para revisar','updates'=>'Extensiones pendientes','unknown'=>'Datos insuficientes'] as $key=>$label): ?><a href="<?= $escape($pageUrl('sites').'&health='.$key.'#nwm-sites') ?>" data-nwm-health-filter="<?= $key ?>" <?= $priorityFilter===$key?'aria-current="true"':'' ?>><?= $label ?><strong><?= $key==='all'?count($sites):$priorities[$key] ?></strong></a><?php endforeach; ?></nav>
<div class="nwm-site-filters" data-nwm-filter-controls hidden><div class="nwm-search"><?= $icon('search') ?><label class="nwm-visually-hidden" for="nwm-site-search">Buscar sitios por nombre o URL</label><input id="nwm-site-search" type="search" placeholder="Buscar por nombre o dirección…" autocomplete="off"></div><label class="nwm-visually-hidden" for="nwm-site-state">Filtrar por estado</label><select id="nwm-site-state"><option value="all">Todos los estados de consulta</option><option value="review">Consulta requiere revisión</option><option value="recent">Inventario reciente</option><option value="never">Sin comprobar</option></select><label class="nwm-visually-hidden" for="nwm-site-health">Filtrar por prioridad</label><select id="nwm-site-health"><?php foreach($priorityFilters as $key=>$label): ?><option value="<?= $key ?>" <?= $key===$priorityFilter?'selected':'' ?>><?= $label ?></option><?php endforeach; ?></select><button class="nwm-button nwm-button--quiet" type="button" data-nwm-clear-filters>Limpiar</button><span class="nwm-filter-count" role="status" data-nwm-filter-count><?= $visible ?> de <?= count($sites) ?> sitios</span></div>
<table class="nwm-site-table"><caption class="nwm-visually-hidden">Información clave por sitio. Entrar abre una ficha independiente.</caption><thead><tr><th scope="col">Sitio</th><th scope="col">Prioridad / consulta</th><th scope="col">Joomla / PHP</th><th scope="col">Pendientes<br><small>en caché</small></th><th scope="col">Configuración / disco</th><th scope="col">Última consulta</th><th scope="col">Acceso</th></tr></thead><tbody>
<?php foreach($sites as $row):
    $state=$states[$row['check_state']??'never_checked']??['Estado desconocido','warning','review'];
    $summary=$row['inventory_summary']??[];$coverage=$summary['coverage']??[];$health=$row['health'];$indicators=$health['indicators'];$last=$row['checks'][0]??null;
    $brief=static fn($key,$field)=>($coverage[$key]??'')==='denied'?'No compartido':($summary[$key][$field]??'—');
    $filters=[];foreach($priorityFilters as $filter=>$label)if(SiteHealth::matches($health,$filter))$filters[]=$filter;
?>
<tr data-nwm-site data-state="<?= $escape($state[2]) ?>" data-health="<?= $escape(implode(' ',$filters)) ?>" data-search="<?= $escape($row['label'].' '.$row['base_url']) ?>" <?= SiteHealth::matches($health,$priorityFilter)?'':'hidden' ?>>
<th scope="row" class="nwm-row-name"><a href="<?= $escape($siteUrl($row['id'])) ?>" title="<?= $escape($row['label']) ?>"><?= $escape($row['label']) ?></a><span title="<?= $escape($row['base_url']) ?>"><?= $escape($row['base_url']) ?></span><a class="nwm-frontend-link" href="<?= $escape($row['base_url']) ?>" target="_blank" rel="noopener noreferrer" aria-label="Abrir web de <?= $escape($row['label']) ?>">Abrir web ↗</a></th>
<td data-label="Prioridad / consulta"><a class="nwm-priority-link" href="<?= $escape($siteUrl($row['id'],'health')) ?>"><span class="nwm-badge nwm-badge--<?= $health['tone'] ?>"><?= $escape($health['label']) ?></span></a><small><?= $escape($state[0]) ?></small></td>
<td data-label="Joomla / PHP" class="nwm-version-cell"><a href="<?= $escape($siteUrl($row['id'],'health')) ?>" title="<?= $escape($indicators['joomla']['detail']) ?>"><strong class="nwm-version nwm-version--<?= $indicators['joomla']['tone'] ?>">J <?= $escape($brief('joomla','version')) ?></strong><small><?= $escape($indicators['joomla']['label']) ?></small></a><a href="<?= $escape($siteUrl($row['id'],'health')) ?>" title="<?= $escape($indicators['runtime']['detail']) ?>"><strong class="nwm-version nwm-version--<?= $indicators['runtime']['tone'] ?>"><?= ($summary['execution_context']??'')==='local_cli'?'CLI':'PHP' ?> <?= $escape($brief('runtime','php_version')) ?></strong><small><?= $escape($indicators['runtime']['label']) ?></small></a></td>
<td data-label="Pendientes en caché"><a class="nwm-priority-link" href="<?= $escape($siteUrl($row['id'],'health')) ?>"><?= $healthBadge($indicators['updates']) ?></a><small><?= ($coverage['updates']??'')==='available'?(($indicators['updates']['cache_fresh']??false)?'Caché reciente':'Comprobar fecha de caché'):(($coverage['updates']??'')==='denied'?'Permiso del Conector':'Sin observación') ?></small></td>
<td data-label="Configuración / disco"><a class="nwm-signal-link" href="<?= $escape($siteUrl($row['id'],'health')) ?>"><span>Config. <?= $healthBadge($indicators['security']) ?></span><span>Disco <?= $healthBadge($indicators['storage']) ?></span></a></td>
<td data-label="Última consulta"><time><?= $last?$escape($date($last['checked_at'])):'Sin comprobar' ?></time><small><?= ($row['connection_type']??'https')==='local'?'Este mismo Joomla':'HTTPS remoto' ?></small><small title="Duración de la última consulta recibida. No es tiempo de carga de la web."><?= isset($summary['collection_ms'])?$escape($summary['collection_ms']).' ms · inventario':'Tiempo aún no medido' ?></small></td>
<td class="nwm-row-action"><a class="nwm-button nwm-button--secondary" href="<?= $escape($siteUrl($row['id'])) ?>" aria-label="Entrar en <?= $escape($row['label']) ?>">Entrar<?= $icon('arrow') ?></a></td></tr>
<?php endforeach; ?></tbody></table>
<div class="nwm-empty" data-nwm-no-results <?= $visible?'hidden':'' ?>><h3>No hay coincidencias</h3><p>Prueba otro nombre, estado o prioridad.</p><a href="<?= $escape($pageUrl('sites')) ?>">Mostrar todos los sitios</a></div>
<?php else: ?><div class="nwm-empty"><h3>Conecta tu primer Joomla</h3><p>Añade un sitio para ver su inventario y prioridades.</p><?php if($canCreate): ?><a class="nwm-button nwm-button--primary" href="<?= $escape($pageUrl('add')) ?>">Conectar primer Joomla<?= $icon('arrow') ?></a><?php endif; ?></div><?php endif; ?>
</section>
<?php require __DIR__.'/references.php'; ?>
